const data = $input.first().json;

// Validare - daca lipsesc date, oprim executia
if (!data.business_owner_email) {
  return [];
}

const rating = data.rating || 0;
const stars = '★'.repeat(rating) + '☆'.repeat(5 - rating);
const businessName = data.business_name || 'Business';
const ownerName = data.owner_first_name || '';
const reviewerName = data.reviewer_first_name || 'Un utilizator';
const comment = data.comment || '';

const html = `
<div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
  <div style="background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); padding: 30px; border-radius: 12px 12px 0 0; text-align: center;">
    <h1 style="color: white; margin: 0; font-size: 24px;">Recenzie nouă! ⭐</h1>
  </div>
  <div style="background: #ffffff; padding: 30px; border: 1px solid #e5e7eb; border-top: none; border-radius: 0 0 12px 12px;">
    <p style="font-size: 16px; color: #374151;">Salut <strong>${ownerName}</strong>,</p>
    <p style="font-size: 16px; color: #374151;"><strong>${reviewerName}</strong> a lăsat o recenzie pentru <strong>${businessName}</strong>:</p>
    <div style="background: #f9fafb; padding: 20px; border-radius: 8px; margin: 20px 0; text-align: center;">
      <p style="font-size: 32px; margin: 0 0 8px 0;">${stars}</p>
      <p style="font-size: 18px; color: #6b7280; margin: 0;">${rating} din 5</p>
    </div>
    ${comment ? `<div style="background: #f0f9ff; padding: 16px; border-left: 4px solid #667eea; border-radius: 4px; margin: 16px 0;"><p style="font-size: 15px; color: #374151; margin: 0; font-style: italic;">"${comment}"</p></div>` : ''}
    <p style="font-size: 14px; color: #9ca3af; margin-top: 24px; text-align: center;">— Echipa OFAI</p>
  </div>
</div>
`;

return [{
  json: {
    to: data.business_owner_email,
    subject: `${businessName} - Recenzie nouă ${stars} (${rating}/5)`,
    html: html
  }
}];
